import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        try:
            n = int(next(iterator))
            k = int(next(iterator))
        except StopIteration:
            break

        adj = [[] for _ in range(n + 1)]
        degree = [0] * (n + 1)

        for _ in range(n - 1):
            u = int(next(iterator))
            v = int(next(iterator))
            adj[u].append(v)
            adj[v].append(u)
            degree[u] += 1
            degree[v] += 1

        if n == 1:
            results.append("0")
            continue

        if k == 0:
            results.append(str(n))
            continue

        removed = [False] * (n + 1)
        q = deque()

        for i in range(1, n + 1):
            if degree[i] <= 1:
                q.append(i)

        layers = {}
        current_layer = 0

        while q:
            node = q.popleft()
            if removed[node]:
                continue

            removed[node] = True
            layers[node] = current_layer

            for neighbor in adj[node]:
                if not removed[neighbor]:
                    degree[neighbor] -= 1
                    if degree[neighbor] == 1:
                        q.append(neighbor)

            if q and (not q or layers.get(q[0], -1) != current_layer):
                pass

            if q and layers.get(q[0], -1) != current_layer:
                current_layer += 1

        count = 0
        for i in range(1, n + 1):
            layer = layers.get(i, float('inf'))
            if layer >= k:
                count += 1

        results.append(str(count))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == '__main__':
    solve()
